// CSD_RATIONALE_BEGIN
// Spider text-to-SQL often has a long unconstrained preamble (schema/question
// narration or delimiter search) followed by a single constrained SQL span.
// This strategy tracks whether we are currently inside that SQL span and, when
// inside, uses two pieces of task-local signal:
//
// 1. schemaBias: a flat bag derived from validTokenGroups, treated as caller-
//    supplied schema-relevant tokens (tables, columns, aliases, keywords).
// 2. fromContext: tokens extracted after the SQL keyword "FROM" from the
//    current constrained prefix, used as a lightweight notion of currently
//    in-scope relation names.
//
// Outside the span, generation is chunked with UnconstrainedChunk until EOS or
// the open delimiter "<<". Inside the span, if the parser says the prefix is
// complete we close immediately; otherwise we adapt between a tight mode
// (ConstrainedStep) when the grammar is narrow and a loose masked-sampling mode
// when it is wide. In loose mode we boost parser-valid candidates that overlap
// with schemaBias and, more strongly, those overlapping with fromContext.
// These tracked signals do not affect validity directly; validity is enforced
// by the parser mask / constrained helpers, while the signals steer selection
// toward schema-consistent SQL continuations.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the unconstrained chunk branch, insideConstrainedOut
//   stays false unless stoppedOpen is true, in which case we set
//   currentConstrainedOut := [], which is valid by parser.IsValidPrefix([]).
//   In the complete-prefix branch, CloseConstrainedSpan sets
//   insideConstrainedOut to false, so the implication is vacuous. In the tight
//   constrained branch, any non-EOS token from ConstrainedStep is appended via
//   AppendConstrainedToken, which preserves parser-validity. In the loose
//   masked branch, MaskValidNextAndEos ensures any non-EOS chosen token is
//   parser-valid; AppendConstrainedToken then preserves validity.
// suffix: In the unconstrained chunk branch, either we remain outside the span
//   (implication vacuous) or we enter with currentConstrainedOut := [], whose
//   length-0 suffix matches generated. CloseConstrainedSpan preserves the
//   relation by atomically appending the closing delimiter and resetting the
//   constrained prefix to []. In both constrained append branches, the same
//   token is appended to generated and currentConstrainedOut by
//   AppendConstrainedToken, so the suffix equality is preserved.
// progress: UnconstrainedChunk appends at most stepsUsed tokens and we set
//   steps := steps + stepsUsed, so |generated| stays within
//   |generatedPrefix| + steps. CloseConstrainedSpan appends exactly one token
//   and we increment steps by 1. Tight and loose constrained branches each
//   consume one decoding step and append at most one token before steps :=
//   steps + 1, or break immediately on EOS. All arithmetic is linear.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var narrowThreshold: nat := 12;
var schemaBias := helpers.FlattenTokenGroups(validTokenGroups);
var fromKeyword: Token := "FROM";
var fromContext: seq<Token] := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant insideConstrainedOut ==> generated[|generated| - |currentConstrainedOut|..] == currentConstrainedOut
  invariant |generated| <= |generatedPrefix| + steps
  invariant cost == 0
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var chunkBudget: nat := maxSteps - steps;
    var chunkedGenerated, stoppedOpen, stoppedEos, stepsUsed := helpers.UnconstrainedChunk(
      lm, prompt, generated, chunkBudget, "<<", eosToken
    );
    generated := chunkedGenerated;
    steps := steps + stepsUsed;
    if stoppedEos {
      break;
    } else if stoppedOpen {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
      fromContext := [];
    }
  } else {
    fromContext := helpers.ExtractAfterKeyword(currentConstrainedOut, fromKeyword);
    if parser.IsCompletePrefix(currentConstrainedOut) {
      var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := closedGenerated;
      insideConstrainedOut := closedInside;
      currentConstrainedOut := closedCurrent;
      fromContext := [];
      steps := steps + 1;
    } else {
      var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
      var constrainedPrompt := prompt + stablePrefix;
      var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);
      if validCount <= narrowThreshold {
        var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
        steps := steps + 1;
        if next == eosToken {
          break;
        } else {
          var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, next
          );
          generated := appendedGenerated;
          insideConstrainedOut := appendedInside;
          currentConstrainedOut := appendedCurrent;
        }
      } else {
        lm.GenerateLogits(constrainedPrompt + currentConstrainedOut);
        var candidates := helpers.TopValidCandidates(
          lm, parser, constrainedPrompt, currentConstrainedOut, 24, eosToken
        );
        var schemaPreferred := helpers.IntersectTokenSets(candidates, schemaBias);
        if |schemaPreferred| > 0 {
          helpers.BoostTokenLogits(lm, schemaPreferred, 5.0);
        }
        var scopedPreferred := helpers.IntersectTokenSets(candidates, fromContext);
        if |scopedPreferred| > 0 {
          helpers.BoostTokenLogits(lm, scopedPreferred, 8.0);
        }
        lm.MaskValidNextAndEos(parser, currentConstrainedOut, eosToken);
        var next := lm.ChooseNextToken();
        helpers.cost := helpers.cost + 1;
        steps := steps + 1;
        if next == eosToken {
          break;
        } else {
          var appendedGenerated2, appendedInside2, appendedCurrent2 := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, next
          );
          generated := appendedGenerated2;
          insideConstrainedOut := appendedInside2;
          currentConstrainedOut := appendedCurrent2;
        }
      }
    }
  }
}

cost := steps;

