// parser_validity: In the open-span branch, `OpenConstrainedSpan` returns an
//   empty active constrained prefix, so validity follows from `parser.IsValidPrefix([])`.
//   In the close branch, we only call `CloseConstrainedSpan` when
//   `parser.IsCompletePrefix(currentConstrainedOut)` is already known, and after
//   closing we are outside constrained mode, so the implication is vacuous. In
//   the one-token constrained branch, masking to valid parser continuations and
//   then using `AppendConstrainedToken` preserves parser validity; if EOS is
//   chosen we break without changing the constrained prefix. In the chunk branch,
//   `ConstrainedSymbol` returns a parser-valid constrained prefix, which we store
//   directly.
// suffix: After opening a span, the active constrained prefix is empty, so the
//   suffix equality holds trivially. After closing, we are outside constrained
//   mode, so the implication is vacuous. In the one-token constrained branch,
//   `AppendConstrainedToken` appends the chosen token to both `generated` and
//   `currentConstrainedOut`, preserving the suffix relation. In the chunk branch,
//   with `stablePrefix := generated[..|generated|-|currentConstrainedOut|]`,
//   assigning `generated := stablePrefix + symbolOut` and
//   `currentConstrainedOut := symbolOut` makes the suffix equality immediate.
// progress: `OpenConstrainedSpan` and `CloseConstrainedSpan` each append exactly
//   one token and we increment `steps` by 1. In the one-token constrained branch,
//   we increment `steps` by 1; either EOS breaks immediately with no further
//   append, or `AppendConstrainedToken` appends exactly one token. In the chunk
//   branch, `ConstrainedSymbol` returns `symbolStepsUsed`; we add that to `steps`,
//   and rebuilding `generated` from `stablePrefix + symbolOut` preserves the
//   linear bound because the constrained suffix length accounts for the tokens
//   produced in that chunk.
// cost accounting: `cost` is initialized before the loop and reset to `steps`
//   after every mutating branch and again before return. The invariant
//   `cost <= steps` is preserved because `cost` is only assigned `steps`, and
//   since `steps <= maxSteps`, the postcondition `cost <= maxSteps` follows.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var flatPreferred := helpers.FlattenTokenGroups(validTokenGroups);
var sqlBias: seq<Token> := ["SELECT", "FROM", "WHERE", "GROUP", "BY", "ORDER", "LIMIT", "JOIN", "ON", ",", "*"];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant insideConstrainedOut ==> generated[|generated| - |currentConstrainedOut|..] == currentConstrainedOut
  invariant |generated| <= |generatedPrefix| + steps
  invariant cost <= steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
    generated := openedGenerated;
    insideConstrainedOut := openedInside;
    currentConstrainedOut := openedCurrent;
    steps := steps + 1;
    cost := steps;
  } else {
    var completeNow := parser.IsCompletePrefix(currentConstrainedOut);
    if completeNow {
      var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := closedGenerated;
      insideConstrainedOut := closedInside;
      currentConstrainedOut := closedCurrent;
      steps := steps + 1;
      cost := steps;
      break;
    } else {
      var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
      var constrainedPrompt := prompt + stablePrefix;
      var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);

      if stepTokenBudget > 1 && steps + stepTokenBudget <= maxSteps && validCount > 4 {
        var symbolOut, hitEos, symbolStepsUsed := helpers.ConstrainedSymbol(
          lm, parser, constrainedPrompt, currentConstrainedOut, stepTokenBudget, eosToken
        );
        generated := stablePrefix + symbolOut;
        currentConstrainedOut := symbolOut;
        steps := steps + symbolStepsUsed;
        cost := steps;
        if hitEos {
          break;
        }
      } else {
        lm.GenerateLogits(constrainedPrompt + currentConstrainedOut);
        var candidates := helpers.TopValidCandidates(
          lm, parser, constrainedPrompt, currentConstrainedOut, 24, eosToken
        );
        var structural := helpers.IntersectTokenSets(candidates, sqlBias);
        if |structural| > 0 {
          helpers.BoostTokenLogits(lm, structural, 8.0);
        }
        if |flatPreferred| > 0 {
          var preferred := helpers.IntersectTokenSets(candidates, flatPreferred);
          if |preferred| > 0 {
            helpers.BoostTokenLogits(lm, preferred, 3.0);
          }
        }

        lm.MaskValidNextAndEos(parser, currentConstrainedOut, eosToken);
        var next := lm.ChooseNextToken();
        helpers.cost := helpers.cost + 1;
        steps := steps + 1;
        cost := steps;

        if next == eosToken {
          break;
        } else {
          var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, next
          );
          generated := appendedGenerated;
          insideConstrainedOut := appendedInside;
          currentConstrainedOut := appendedCurrent;
        }
      }
    }
  }
}

cost := steps;
